import {unduhXlsx,S} from './xlsx-tulis.js';
import {COLORS,PHASES,parseCode,makeCode} from './core.js';
import {blockFor,boundaryDistanceMeters} from './gis.js';
import {createApi} from './api.js';
import {openLocal,putMeta,getMeta,cacheTree,cachedTree,enqueue,pending,syncQueue} from './queue.js';

const $=id=>document.getElementById(id), api=createApi();
let db,setup=null,identity=null,current=null,currentCode='',locationFix=null,scanner=null,map=null,polygons=null,points=null,session=null,syncing=false,syncAgain=false;
const canSensus=()=>identity?.role==='admin'||identity?.job==='sensus';
const canHarvest=()=>identity?.role==='admin'||identity?.harvestAccess;
const isAdmin=()=>identity?.role==='admin';
const nameOf=f=>{const p=f?.properties||{};return String(p.Nama_Blok||p.NAMA_BLOK||p.nama_blok||p.BLOK||p.Blok||p.blok||p.name||p.Nama||'').trim();};
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Jakarta',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const uuid=()=>crypto.randomUUID();
const clientTree=t=>t&&({code:t.code,block:t.block,row:t.row_label,lat:t.lat,lng:t.lng,accuracy:t.accuracy,phase:t.phase,condition:t.condition,note:t.note,color:t.color,awaiting:t.awaiting_decision,version:t.version});
const roleText=()=>isAdmin()?'Admin':canSensus()?'Petugas sensus':canHarvest()?'Petugas panen':'Pemantau';
function message(id,text,error=false){$(id).textContent=text;$(id).classList.toggle('notice',error);}
function switchView(view){for(const node of document.querySelectorAll('[data-panel]'))node.hidden=node.dataset.panel!==view;for(const b of document.querySelectorAll('[data-view]'))b.classList.toggle('active',b.dataset.view===view);if(view==='map'&&map)setTimeout(()=>map.invalidateSize(),0);if(view==='queue')renderQueue();}
for(const b of document.querySelectorAll('[data-view]'))b.onclick=()=>switchView(b.dataset.view);
function setIdentity(user){identity=user;$('auth').hidden=!!user;$('workspace').hidden=!user;if(!user){$('status').textContent='Belum masuk';return;}$('profile').textContent=`${user.name} · ${roleText()}`;$('labelsTab').hidden=!isAdmin();$('reportsTab').hidden=!(isAdmin()||user.reportAccess);$('openSession').hidden=!canSensus();$('finishSession').hidden=!canSensus();}
async function applySetup(value){
 if(!value?.boundary||!Array.isArray(value.boundary.features)||!Array.isArray(value.batches)||!Array.isArray(value.sessions))throw Error('Peta atau data batch tidak valid.');
 setup=value;await putMeta(db,'setup',value);const previous=$('mapBlock').value;
 $('mapBlock').replaceChildren(new Option('Pilih blok',''));[...new Set(value.boundary.features.map(nameOf).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'id')).forEach(n=>$('mapBlock').add(new Option(n,n)));if([...$('mapBlock').options].some(x=>x.value===previous))$('mapBlock').value=previous;
 const batch=$('batchSelect').value;$('batchSelect').replaceChildren(new Option('Pilih batch',''));for(const b of value.batches){const o=new Option(`${String(b.id).slice(0,8)} · ${Number(b.quantity).toLocaleString('id-ID')} kode`,b.id);$('batchSelect').add(o);}if([...$('batchSelect').options].some(o=>o.value===batch))$('batchSelect').value=batch;
 if(map){if(polygons)map.removeLayer(polygons);polygons=L.geoJSON(value.boundary,{style:{color:'#327a50',weight:2,fillOpacity:.04},onEachFeature:(f,layer)=>{const n=document.createElement('span');n.textContent=nameOf(f);layer.bindTooltip(n,{direction:'center'});}}).addTo(map);}
 if(session){session=value.sessions.find(x=>x.id===session.id)||null;showSession();}
}
function showSession(){if(session){$('sessionInfo').textContent=`Sesi terbuka · ${session.block}`;$('mapBlock').value=session.block;}else $('sessionInfo').textContent='Belum ada sesi dipilih.';}
async function updateQueue(){const rows=await pending(db,identity.id);$('queueCount').textContent=String(rows.length);return rows;}
async function renderQueue(){if(!identity)return;const rows=await updateQueue(),root=$('queueList');root.replaceChildren();if(!rows.length){root.textContent='Semua catatan di HP ini sudah terkirim.';return;}for(const item of rows){const d=document.createElement('div');d.className='queue-item';const t=document.createElement('strong'),p=document.createElement('p');t.textContent=`${item.event.type} · ${item.status==='periksa'?'Perlu diperiksa':'Belum terkirim'}`;p.textContent=item.event.code+(item.message?` · ${item.message}`:'');d.append(t,p);root.append(d);}}
async function sync(){
 if(!identity)return;if(syncing){syncAgain=true;return;}syncing=true;$('sync').disabled=true;message('syncText','Menghubungkan dan memeriksa akun…');
 try{identity=await api.verify();setIdentity(identity);await applySetup(await api.rpc('ip_get_setup'));const result=await syncQueue(db,identity.id,async event=>clientTree(await api.rpc('ip_apply_event',{p_event:event})));const rows=await updateQueue();message('syncText',rows.length?`${rows.length} catatan belum terkirim. Buka Antrean untuk memeriksa.`:'Semua catatan di HP ini tersinkron.',!!rows.length);$('status').textContent=rows.length?'Ada antrean':'Tersinkron';if(currentCode)await lookup(currentCode,true);}
 catch(e){const rows=await updateQueue();message('syncText',`${e.message} ${rows.length} catatan tersimpan di HP.`,true);$('status').textContent='Belum tersinkron';}finally{syncing=false;$('sync').disabled=false;if(syncAgain){syncAgain=false;sync().catch(()=>{});}}
}
async function queueEvent(event,tree=null){if(!identity)throw Error('Masuk terlebih dahulu.');const rows=await pending(db,identity.id);if(event.type==='register'&&rows.some(x=>x.event.type==='register'&&x.event.code===event.code))throw Error('Pendaftaran barcode ini sudah menunggu sinkronisasi.');await enqueue(db,identity.id,event,tree);await updateQueue();$('status').textContent='Belum tersinkron';message('syncText','Tersimpan di HP, menunggu konfirmasi server.');sync().catch(()=>{});}
async function locate(){
 if(!navigator.geolocation)throw Error('GPS tidak tersedia di perangkat ini.');
 $('gpsStatus').textContent='Mencari posisi GPS…';const p=await new Promise((resolve,reject)=>navigator.geolocation.getCurrentPosition(resolve,reject,{enableHighAccuracy:true,timeout:20000,maximumAge:5000}));
 locationFix={lat:p.coords.latitude,lng:p.coords.longitude,accuracy:p.coords.accuracy,time:Date.now()};const match=blockFor(setup?.boundary?.features||[],locationFix.lat,locationFix.lng);
 $('gpsStatus').textContent=`GPS ±${Math.round(locationFix.accuracy)} m · ${match?'Blok '+nameOf(match):'Blok belum terdeteksi; geser ke dalam blok.'}`;if($('registerBlock'))$('registerBlock').value=match?nameOf(match):'';if(map){map.setView([locationFix.lat,locationFix.lng],18);if(window.gpsMarker)map.removeLayer(window.gpsMarker);window.gpsMarker=L.circleMarker([locationFix.lat,locationFix.lng],{radius:6,color:'#1266d4',fillOpacity:1}).addTo(map);}return match;
}
$('gpsButton').onclick=()=>locate().catch(e=>message('gpsStatus','GPS belum tersedia: '+e.message,true));
function fragment(html){const t=document.createElement('template');t.innerHTML=html;return t.content;}
function addOption(select,value,label){select.add(new Option(label,value));}
function showNew(code){
 const panel=$('treePanel');panel.replaceChildren();if(!canSensus()){panel.textContent='Barcode belum terdaftar. Hubungi petugas sensus.';return;}
 const parts=parseCode(code),batch=setup?.batches?.find(x=>x.id===parts.batchId);if(!batch||parts.serial>batch.quantity){panel.textContent='Barcode belum ada di daftar batch pada HP. Sinkronkan dahulu.';return;}
 panel.append(fragment(`<div class="detail"><h2>Daftarkan pokok baru</h2><p>Blok diambil dari GPS. Periksa posisinya, pilih baris dan fase awal sesuai kondisi sebenarnya.</p><form id="registerForm" class="grid"><label>Blok dari GPS<input id="registerBlock" readonly required></label><label>Nomor baris<input id="registerRow" maxlength="40" required></label><label>Fase awal<select id="registerPhase" required><option value="">Pilih fase</option></select></label><button>Simpan pendaftaran</button></form><p class="hint">Jika tidak ada sinyal, pendaftaran menunggu pemeriksaan database saat tersinkron.</p></div>`));
 const match=locationFix&&Date.now()-locationFix.time<60000?blockFor(setup.boundary.features,locationFix.lat,locationFix.lng):null;$('registerBlock').value=match?nameOf(match):'';PHASES.forEach(x=>addOption($('registerPhase'),x,x));
 $('registerForm').onsubmit=async e=>{e.preventDefault();try{const fix=locationFix;if(!fix||Date.now()-fix.time>60000)throw Error('Perbarui GPS terlebih dahulu.');const feature=blockFor(setup.boundary.features,fix.lat,fix.lng);if(!feature||nameOf(feature)!==$ ('registerBlock').value)throw Error('Posisi belum tepat berada dalam blok. Perbarui GPS.');const near=boundaryDistanceMeters(feature,fix.lat,fix.lng)<=fix.accuracy;if((near||fix.accuracy>30)&&!confirm(`GPS ±${Math.round(fix.accuracy)} m ${near?'dan dekat batas blok':''}. Pastikan benar di blok ${nameOf(feature)}. Lanjutkan?`))return;const event={id:uuid(),type:'register',code,block:nameOf(feature),row:$('registerRow').value.trim(),phase:$('registerPhase').value,lat:fix.lat,lng:fix.lng,accuracy:fix.accuracy};if(!event.row||!event.phase)throw Error('Baris dan fase awal wajib diisi.');const provisional={code:event.code,block:event.block,row:event.row,lat:event.lat,lng:event.lng,accuracy:event.accuracy,phase:event.phase,condition:'belum_sensus',note:'',color:null,awaiting:false,version:1,_pendingRegistration:true};await queueEvent(event,provisional);current=provisional;showTree(provisional);message('scanMessage','Pendaftaran tersimpan di HP, belum dikonfirmasi server. Silakan isi sensus.');}catch(err){message('scanMessage',err.message,true);}};
}
function showTree(tree,history=[]){
 const panel=$('treePanel');panel.replaceChildren();panel.append(fragment(`<div class="detail"><h2>Identitas pokok</h2><div class="details-grid"><div><small>Blok</small><strong id="vBlock"></strong></div><div><small>Baris</small><strong id="vRow"></strong></div><div><small>Fase</small><strong id="vPhase"></strong></div><div><small>Kondisi</small><strong id="vCondition"></strong></div><div><small>Pita saat ini</small><strong id="vColor"></strong></div></div><p id="treeNotice" class="hint"></p><div id="treeActions"></div><details><summary>Riwayat terbaru</summary><div id="history"></div></details></div>`));
 $('vBlock').textContent=tree.block;$('vRow').textContent=tree.row;$('vPhase').textContent=tree.phase+(tree.awaiting?' · menunggu keputusan admin':'');$('vCondition').textContent=tree.condition;$('vColor').textContent=tree.color||'Belum tercatat';$('treeNotice').textContent=tree._pendingRegistration?'Pendaftaran belum dikonfirmasi server. Data ini masih tersimpan di HP.':(tree.note||'');
 const hist=$('history');if(!history.length)hist.textContent='Riwayat belum tersedia di HP ini.';for(const e of history){const p=document.createElement('p');p.textContent=`${e.created_at?.slice(0,10)||''} · ${e.type} · ${e.petugas||'Petugas'}`;hist.append(p);}
 const actions=$('treeActions');
 if(canSensus()){
  actions.append(fragment(`<form id="censusForm" class="grid"><label>Kondisi<select id="censusCondition" required><option value="">Pilih kondisi</option><option value="hidup">Hidup</option><option value="mati">Mati</option><option value="lainnya">Lainnya</option></select></label><label>Warna pita<select id="censusColor"><option value="">Belum ada pita</option></select></label><label>Keterangan<input id="censusNote" maxlength="500"></label><button>Simpan sensus</button></form>`));COLORS.forEach(([c,n])=>addOption($('censusColor'),c,`${c} · ${n}`));
  $('censusForm').onsubmit=async e=>{e.preventDefault();try{if(!session||session.block!==tree.block)throw Error('Pilih atau mulai sesi sensus untuk blok '+tree.block+'.');const condition=$('censusCondition').value,note=$('censusNote').value.trim();if(condition==='lainnya'&&!note)throw Error('Isi keterangan untuk kondisi lainnya.');const event={id:uuid(),type:'census',code:tree.code,expectedVersion:tree.version,sessionId:session.id,condition,color:$('censusColor').value,note,date:today()};const q=await pending(db,identity.id);if(q.some(x=>x.event.type==='census'&&x.event.sessionId===session.id&&x.event.code===tree.code))throw Error('Pokok sudah ada pada antrean sesi ini.');await queueEvent(event);message('scanMessage','Sensus disimpan di HP; kondisi diterapkan setelah sesi selesai.');}catch(err){message('scanMessage',err.message,true);}};
 }
 if(canHarvest()){
  const button=document.createElement('button');button.type='button';button.textContent='Konfirmasi panen';button.disabled=tree.awaiting||tree.condition!=='hidup'||!tree.color;button.onclick=async()=>{if(!confirm(`Konfirmasi panen pokok ${tree.code}, blok ${tree.block} baris ${tree.row}, fase ${tree.phase}, pita ${tree.color}?`))return;try{await queueEvent({id:uuid(),type:'harvest',code:tree.code,expectedVersion:tree.version,phase:tree.phase,color:tree.color,date:today()});message('scanMessage','Panen disimpan di HP; tunggu sinkronisasi.');button.disabled=true;}catch(e){message('scanMessage',e.message,true);}};actions.append(button);
 }
 if(isAdmin()&&tree.awaiting){for(const [action,label] of [['r4','Lanjut R4'],['tanam_ulang','Tanam ulang · mulai PC']]){if(action==='r4'&&tree.phase!=='R3')continue;const b=document.createElement('button');b.type='button';b.className='quiet';b.textContent=label;b.onclick=async()=>{if(!confirm(`Terapkan keputusan ${label} untuk pokok ini?`))return;try{await queueEvent({id:uuid(),type:'decision',code:tree.code,expectedVersion:tree.version,action});message('scanMessage','Keputusan disimpan di HP; tunggu sinkronisasi.');}catch(e){message('scanMessage',e.message,true);}};actions.append(b);}}
}
async function lookup(raw,quiet=false){
 const parsed=parseCode(raw);currentCode=parsed.code;$('code').value=parsed.code;let tree=null,history=[];
 try{const data=await api.rpc('ip_get_tree',{p_code:parsed.code});if(data){tree=clientTree(data.tree);history=data.history||[];await cacheTree(db,tree);}else if((await cachedTree(db,parsed.code))?._pendingRegistration){tree=await cachedTree(db,parsed.code);}else{current=null;if(!quiet)message('scanMessage','Barcode belum terdaftar.');showNew(parsed.code);return;}}
 catch(e){if(e.status)throw e;tree=await cachedTree(db,parsed.code);if(!tree){current=null;message('scanMessage','Offline atau data belum tersedia. Pendaftaran akan diperiksa server saat sinkron.',true);showNew(parsed.code);return;}if(!quiet)message('scanMessage','Menampilkan salinan di HP; sinkronkan untuk memastikan data terbaru.',true);}
 current=tree;if(!quiet&&navigator.onLine)message('scanMessage','Data pokok ditemukan.');showTree(tree,history);
}
$('lookupForm').onsubmit=e=>{e.preventDefault();lookup($('code').value).catch(err=>message('scanMessage',err.message,true));};
$('camera').onclick=async()=>{try{if(!navigator.mediaDevices?.getUserMedia)throw Error('Kamera memerlukan HTTPS dan browser yang mendukung.');$('video').hidden=false;$('cameraStop').hidden=false;const reader=new ZXingBrowser.BrowserMultiFormatReader();let handled=false;scanner=await reader.decodeFromConstraints({video:{facingMode:{ideal:'environment'}},audio:false},$('video'),(result)=>{if(!result||handled)return;handled=true;if(scanner){scanner.stop();scanner=null;}$('video').hidden=true;$('cameraStop').hidden=true;lookup(result.getText()).catch(e=>message('scanMessage',e.message,true));});if(handled&&scanner){scanner.stop();scanner=null;}}catch(e){message('scanMessage','Kamera belum dapat dibuka: '+e.message,true);}};
$('cameraStop').onclick=()=>{scanner?.stop();scanner=null;$('video').hidden=true;$('cameraStop').hidden=true;};
$('openSession').onclick=async()=>{const block=$('mapBlock').value;if(!block){message('mapMessage','Pilih blok dahulu.',true);return;}try{session=setup?.sessions?.find(x=>x.block===block)||null;if(!session){if(!canSensus())throw Error('Akun tidak memiliki hak sensus.');session=await api.rpc('ip_start_session',{p_id:uuid(),p_block:block});setup.sessions.push(session);await putMeta(db,'setup',setup);}await putMeta(db,'session:'+identity.id,session);showSession();message('mapMessage','Sesi dapat digunakan beberapa hari; mulai pindai pokok.');}catch(e){message('mapMessage','Sesi baru perlu internet: '+e.message,true);}};
$('finishSession').onclick=async()=>{try{if(!session)throw Error('Pilih sesi yang terbuka.');const rows=await pending(db,identity.id);if(rows.some(x=>x.event.sessionId===session.id))throw Error('Masih ada antrean sesi ini di HP. Sinkronkan terlebih dahulu.');if(!confirm(`Terapkan hasil sensus blok ${session.block}? Pastikan semua petugas sudah menyinkronkan HP mereka.`))return;const r=await api.rpc('ip_apply_session',{p_id:session.id});message('mapMessage',`Sesi diterapkan · ${r.count||0} pokok.`);session=null;await putMeta(db,'session:'+identity.id,null);await applySetup(await api.rpc('ip_get_setup'));showSession();}catch(e){message('mapMessage',e.message,true);}};
$('mapBlock').onchange=()=>{const f=setup?.boundary?.features?.find(x=>nameOf(x)===$('mapBlock').value);if(f&&map)map.fitBounds(L.geoJSON(f).getBounds(),{padding:[20,20]});};
$('refreshMap').onclick=async()=>{try{const block=$('mapBlock').value;if(!block)throw Error('Pilih blok terlebih dahulu.');const b=map.getBounds(),list=await api.rpc('ip_get_map',{p_block:block,p_south:b.getSouth(),p_west:b.getWest(),p_north:b.getNorth(),p_east:b.getEast()});points.clearLayers();for(const t of list.slice(0,2000)){const color=t.condition==='mati'?'#ad2f24':t.condition==='lainnya'?'#df9100':'#217a42';L.circleMarker([t.lat,t.lng],{radius:3,color,weight:1,fillOpacity:.9}).addTo(points).on('click',()=>{switchView('scan');lookup(t.code).catch(e=>message('scanMessage',e.message,true));});}message('mapMessage',list.length>2000?'Lebih dari 2.000 titik. Perbesar peta untuk melihat sisanya.':`${list.length} titik ditampilkan.`);}catch(e){message('mapMessage','Peta titik perlu internet: '+e.message,true);}};
$('batchForm').onsubmit=async e=>{e.preventDefault();try{const quantity=Number($('batchQuantity').value);if(!Number.isInteger(quantity)||quantity<1||quantity>2000000)throw Error('Jumlah harus 1–2.000.000.');if(!confirm(`Buat batch ${quantity.toLocaleString('id-ID')} kode unik?`))return;const result=await api.rpc('ip_make_batch',{p_id:uuid(),p_quantity:quantity});await applySetup(await api.rpc('ip_get_setup'));$('batchSelect').value=result.id;message('labelMessage','Batch dibuat. Cetak sampel dan uji sebelum mencetak banyak.');}catch(err){message('labelMessage',err.message,true);}};
$('printLabels').onclick=async()=>{let win;try{const batch=setup?.batches?.find(b=>b.id===$('batchSelect').value),start=Number($('labelStart').value),count=Number($('labelCount').value);if(!batch||!Number.isInteger(start)||!Number.isInteger(count)||start<1||count<1||count>500||start+count-1>batch.quantity)throw Error('Periksa batch, nomor awal, dan jumlah label.');win=window.open('','_blank');if(!win)throw Error('Izinkan pop-up agar halaman cetak dapat dibuka.');win.document.write('<!doctype html><title>Label Identitas Pokok</title><style>@page{size:A4;margin:8mm}body{font:8px sans-serif}.labels{display:grid;grid-template-columns:repeat(6,1fr);gap:2mm}.label{border:1px dashed #bbb;min-height:30mm;text-align:center;break-inside:avoid;overflow-wrap:anywhere}.label svg{width:22mm;height:22mm}button{padding:8px}@media print{button{display:none}}</style><button onclick="window.print()">Cetak / simpan PDF</button><p>Batch '+batch.id+' · nomor '+start+'–'+(start+count-1)+'</p><div class="labels"></div>');const area=win.document.querySelector('.labels'),writer=new ZXingBrowser.BrowserQRCodeSvgWriter(),hints=new Map([[0,'M']]);for(let i=0;i<count;i++){const code=makeCode(batch.id,start+i),div=win.document.createElement('div');div.className='label';div.append(writer.write(code,150,150,hints));const text=win.document.createElement('div');text.textContent=code;div.append(text);area.append(div);}message('labelMessage',`${count} label disiapkan. Periksa ukuran dan pindai sampel sebelum mencetak massal.`);}catch(e){if(win)win.close();message('labelMessage',e.message,true);}};
$('loadReports').onclick=async()=>{try{const sessions=await api.rpc('ip_list_sessions');const root=$('reportList');root.replaceChildren();if(!sessions.length){root.textContent='Belum ada sesi sensus.';return;}for(const item of sessions){const box=document.createElement('div');box.className='queue-item';const title=document.createElement('strong');title.textContent=`${item.block} · ${String(item.created_at).slice(0,10)} · ${item.state==='open'?'Berjalan':'Diterapkan'}`;const desc=document.createElement('p');desc.textContent=`${item.total} pokok · hidup ${item.hidup} · mati ${item.mati} · lainnya ${item.lainnya}`;const button=document.createElement('button');button.textContent='Unduh Excel bagian 1';let after='',part=1;button.onclick=async()=>{try{button.disabled=true;const rows=await api.rpc('ip_session_export',{p_id:item.id,p_after:after,p_limit:1000});if(!rows.length){button.textContent='Semua bagian selesai';return;}const headers=['Kode','Blok','Baris','Fase','Kondisi','Warna pita','Keterangan','Tanggal','Petugas'];const fields=['tree_code','block','row_label','phase','condition','color','note','tanggal','petugas'];await unduhXlsx(`Sensus-${item.block}-${part}.xlsx`,[{nama:'Sensus',baris:[headers.map(S.kepala),...rows.map(r=>fields.map(k=>S.teks(String(r[k]??'')) ))]}]);after=rows[rows.length-1].tree_code;part++;button.textContent=rows.length<1000?'Semua bagian selesai':`Unduh Excel bagian ${part}`;button.disabled=rows.length<1000;}catch(e){button.disabled=false;message('reportMessage',e.message,true);}};box.append(title,desc,button);root.append(box);}message('reportMessage','Rekap diperbarui.');}catch(e){message('reportMessage',e.message,true);}};
$('loginForm').onsubmit=async e=>{e.preventDefault();try{message('authMessage','Memeriksa akun…');const user=await api.login($('username').value,$('pin').value);$('pin').value='';setIdentity(user);session=await getMeta(db,'session:'+user.id)||null;showSession();await sync();}catch(err){message('authMessage','Belum berhasil masuk: '+err.message,true);}};
$('sync').onclick=()=>sync();$('logout').onclick=async()=>{const q=identity?await pending(db,identity.id):[];if(q.length&&!confirm(`Masih ada ${q.length} catatan di HP untuk akun ini. Keluar? Data hanya akan dikirim setelah akun yang sama masuk kembali.`))return;scanner?.stop();api.logout();session=null;current=null;setIdentity(null);};
window.addEventListener('online',()=>sync());
async function boot(){try{db=await openLocal();map=L.map('map').setView([-7.12,109.05],14);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap contributors'}).addTo(map);points=L.layerGroup().addTo(map);const cached=await getMeta(db,'setup');if(cached)await applySetup(cached);if(api.hasSession()&&api.identity()){setIdentity(api.identity());session=await getMeta(db,'session:'+identity.id)||null;showSession();await sync();}if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});}catch(e){message('authMessage','Aplikasi belum siap: '+e.message,true);}}
boot();
